.";        }        catch (Exception ex)        {            result.ExitCode = 3;            result.ErrorMessage = ex.Message;        }        Completed?.Invoke(this, result);        return result;    }    private static IEnumerable<string> ReadAll(System.IO.StreamReader reader)    {        var lines = new List<string>();        string? line;        while ((line = reader.ReadLine()) is not null)            lines.Add(line);        return lines;    }    private static string ComputeOutputPath(string source, string targetFps)    {        var suffix = targetFps.Replace("x", "mul");        var fi = new FileInfo(source);        var name = Path.GetFileNameWithoutExtension(source);        return Path.Combine(fi.DirectoryName ?? string.Empty,            $"{name}_{suffix}fps_master.mp4");    }    private static string Quote(string s) => s;    private static readonly Regex SegmentRegex = new(@"╨б╨╡╨│╨╝╨╡╨╜╤В\s+(\d+)\s*/\s*(\d+)", RegexOptions.Compiled);    private static readonly Regex RifeSummaryRegex = new(@"RIFE:\s*(\d+)\s*╨║╨░╨┤╤А╨╛╨▓,\s*(\d+)\s*╤Б╨╡╨│╨╝╨╡╨╜╤В╨╛╨▓", RegexOptions.Compiled);    private static readonly Regex PercentRegex = new(@"(\d+(?:\.\d+)?)\s*%", RegexOptions.Compiled);    private void ApplyLogLine(string line, EngineProgress progress, EngineResult result,        ref bool verificationStarted)    {        var lower = line.ToLowerInvariant();        if (lower.Contains("╤А╨╕╤Д╨╡:") || lower.Contains("rife:"))        {            var m = RifeSummaryRegex.Match(line);            if (m.Success)            {                progress.TotalSegments = int.Parse(m.Groups[2].Value);                progress.Stage = "RIFE AI";                progress.Message = $"╨б╨╡╨│╨╝╨╡╨╜╤В╨╛╨▓: {progress.TotalSegments}";                progress.Percent = 0;            }            return;        }        var sm = SegmentRegex.Match(line);        if (sm.Success)        {            progress.CurrentSegment = int.Parse(sm.Groups[1].Value);            progress.TotalSegments = int.Parse(